public sealed class SqsHostedConsumer : IDisposable
{
    public event EventHandler<SqsMessage>? MessageReceived;

    // Do not do this on a hosted service:
    public Action<SqsMessage>? UnsafeHook;

    public void OnMessage(SqsMessage message)
    {
        MessageReceived?.Invoke(this, message);
        UnsafeHook?.Invoke(message);
    }

    public void Dispose() => MessageReceived = null;
}

public sealed record SqsMessage(string MessageId, string Body);

public async Task ProcessBatchAsync(SqsHostedConsumer host, CancellationToken ct)
{
    EventHandler<SqsMessage> handler = (_, msg) => Console.WriteLine(msg.MessageId);
    host.MessageReceived += handler;
    try
    {
        await host.DrainAsync(ct);
    }
    finally
    {
        host.MessageReceived -= handler;
    }
}

protected virtual void OnMessageReceived(SqsMessage message)
{
    var handlers = MessageReceived;
    if (handlers is null) return;

    foreach (var d in handlers.GetInvocationList())
    {
        try { ((EventHandler<SqsMessage>)d)(this, message); }
        catch (Exception ex) { LogHandlerFailure(ex); }
    }
}
